from pptx import Presentation
from pptx.util import Inches
prs = Presentation('/app/output/final_deck.pptx')
for i, s in enumerate(prs.slides, 1):
    texts = []
    for sh in s.shapes:
        if sh.has_text_frame:
            for p in sh.text_frame.paragraphs:
                t = p.text.strip()
                if t and len(t) > 3:
                    texts.append(t[:60])
    print(f'--- Slide {i} ---')
    for t in texts[:6]:
        print(f'  {t}')
    print()
"

raw_arguments.command:
python3 -c "
from pptx import Presentation
from pptx.util import Inches
prs = Presentation('/app/output/final_deck.pptx')
for i, s in enumerate(prs.slides, 1):
    texts = []
    for sh in s.shapes:
        if sh.has_text_frame:
            for p in sh.text_frame.paragraphs:
                t = p.text.strip()
                if t and len(t) > 3:
                    texts.append(t[:60])
    print(f'--- Slide {i} ---')
    for t in texts[:6]:
        print(f'  {t}')
    print()
"
